#!/bin/bash
set -e

CYAN='\e[1;36m'
GREEN='\e[1;32m'
RED='\e[1;31m'
NC='\e[0m'

if [ "$(id -u)" -ne 0 ]; then
    echo -e "${RED}[-] Please run as root (sudo).${NC}"
    exit 1
fi

echo -e "${CYAN}[*] Installing NexusNet Personal Edition...${NC}"

if command -v apt-get >/dev/null 2>&1; then
    apt-get update -y >/dev/null 2>&1 || true
    apt-get install -y python3 python3-pip curl tor tor-geoipdb >/dev/null 2>&1 || true
fi

pip3 install --break-system-packages 'requests[socks]' >/dev/null 2>&1 || \
pip3 install 'requests[socks]' >/dev/null 2>&1 || true

echo -e "${CYAN}[*] Writing NexusNet...${NC}"

python3 -c '
import base64
b64 = """
"""
data = base64.b64decode(b64)
with open("/usr/local/bin/nexusnet", "wb") as f:
    f.write(data)
print("OK")
'
chmod +x /usr/local/bin/nexusnet
ln -sf /usr/local/bin/nexusnet /usr/local/bin/NexusNet 2>/dev/null || true
echo -e "${GREEN}[+] Installed successfully!${NC}"
echo -e "${GREEN}[+] Run with:  nexusnet${NC}"
echo
exec /usr/local/bin/nexusnet </dev/tty
